  2274  unsigned PackMachFat::check_fat_head()
  2275  {
  2276      struct Mach_fat_arch const *const arch = &fat_head.arch[0];
  2277      unsigned nfat = fat_head.fat.nfat_arch;
  2278      if (Mach_fat_header::FAT_MAGIC!=fat_head.fat.magic
