  2280          return 0;
  2281      }
  2282      for (unsigned j=0; j < nfat; ++j) {
  2283          unsigned const align = arch[j].align;
  2284          if (24 < align) {
  2285              char msg[80]; snprintf(msg, sizeof(msg),
  2286                  "bad fat_arch alignment 0x%x > 24", align);
  2287              throwCantPack(msg);
  2288          }
  2289          unsigned const mask = ~(~0u<<align);
  2290          unsigned const size = arch[j].size;
  2291          unsigned const offset = arch[j].offset;
  2292          if (align < 12 || align > 24) { // heuristic
  2293              throwUnknownExecutableFormat("align", 0);
  2294          }
  2295          if (mask > size) {
  2296              throwUnknownExecutableFormat("size", 0);
  2297          }
  2298          if (mask & offset
  2299          ||  (unsigned)fi->st_size_orig() < size + offset
  2300          ||  (unsigned)fi->st_size_orig() <= offset) {  // redundant unless overflow
  2301              throwUnknownExecutableFormat("offset", 0);
  2302          }
  2303      }
  2304      return nfat;
  2305  }
