   174      _flags = flags;
   175      _shflags = shflags;
   176      _mode = 0;
   177      _offset = 0;
   178      _length = 0;
   179      if (!super::do_sopen()) {
   180          if (errno == ENOENT)
   181              throw FileNotFoundException(_name, errno);
   182          else if (errno == EEXIST)
   183              throw FileAlreadyExistsException(_name, errno);
